mapper.select:
select ifnull(sum(money),0) from user_money_details where user_id=#{userId}
and classify=#{classify}
and classify in (5,6)
and date_format(create_time,'%Y-%m-%d')=date_format(#{time},'%Y-%m-%d')
and date_format(create_time,'%Y-%m')=date_format(#{time},'%Y-%m')
and date_format(create_time,'%Y')=date_format(#{time},'%Y')

select * from user_money_details
where user_id=#{userId} and by_user_id=#{byUserId}
  and classify=#{classify}
order by create_time desc
